const sceneRows = $input.first().json.rows;
const projectId = sceneRows[0].project_id;

const scenes = sceneRows.map(row => ({
  id: row.scene_id,
  scene_number: row.scene_number,
  chapter_number: row.chapter_number,
  title: row.scene_title,
  summary: row.summary,
  characters_present: JSON.parse(row.characters_present || '[]'),
  location: row.location,
  time_period: row.time_period,
  emotional_tone: row.emotional_tone,
  word_count: row.word_count || 0,
  production_metadata: row.production_metadata || {}
}));

const batchSize = 5;
const batches = [];
for (let i = 0; i < scenes.length; i += batchSize) {
  batches.push(scenes.slice(i, i + batchSize));
}

return [{
  json: {
    project_id: projectId,
    title: sceneRows[0].title,
    language: sceneRows[0].language,
    scenes: scenes,
    total_scenes: scenes.length,
    batches: batches,
    total_batches: batches.length
  }
}];

const responseText = $input.first().json.response || '{}';
let shotData = [];

try {
  const jsonMatch = responseText.match(/\[[\s\S]*\]/);
  if (jsonMatch) {
    shotData = JSON.parse(jsonMatch[0]);
  } else {
    const objMatch = responseText.match(/\{[\s\S]*\}/);
    if (objMatch) {
      const parsed = JSON.parse(objMatch[0]);
      shotData = Object.entries(parsed).map(([key, val]) => ({ scene_id: key, ...val }));
    }
  }
} catch (e) {
  shotData = [];
}

const scenes = $('Execute Logic').item.json.scenes;
const projectId = $('Execute Logic').item.json.project_id;

let totalShots = 0;
const shotInserts = [];

for (const sd of shotData) {
  const scene = scenes.find(s => s.id === sd.scene_id);
  if (!sd.shots) continue;

  for (const shot of sd.shots) {
    totalShots++;
    shotInserts.push({
      json: {
        scene_id: sd.scene_id,
        project_id: projectId,
        shot_number: shot.shot_number,
        shot_type: shot.shot_type,
        duration_seconds: shot.duration_seconds || 5,
        description: shot.description || '',
        characters_in_shot: JSON.stringify(shot.characters_in_shot || []),
        camera_movement: shot.camera_movement || 'static',
        transition_in: shot.transition_in || 'cut',
        transition_out: shot.transition_out || 'cut',
        priority: shot.priority || 'medium',
        vfx_required: shot.vfx_required || false,
        dialogue_in_shot: shot.dialogue_in_shot || false,
        state: 'planned'
      }
    });
  }
}

const totalDuration = shotInserts.reduce((sum, s) => sum + s.json.duration_seconds, 0);

return [{
  json: {
    project_id: projectId,
    shot_inserts: shotInserts,
    total_shots: totalShots,
    total_scenes: shotData.length,
    total_duration_seconds: totalDuration,
    total_duration_formatted: `${Math.floor(totalDuration / 60)}m ${totalDuration % 60}s`
  }
}];

